    return {
        "summary": report.summary,
        "entries": report.entries,
        "report_md": f"/reports/{md_path.name}",
        "report_json": f"/reports/{json_path.name}",
    }


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5080, debug=False)

